  id TEXT PRIMARY KEY,
  full_name TEXT NOT NULL,
  mssv TEXT NOT NULL UNIQUE,
  email TEXT NOT NULL UNIQUE,
  math_score INT NOT NULL,
  coding_score INT NOT NULL,
  regional_count INT NOT NULL,
  wf_count INT NOT NULL,
  topic_scores JSONB NOT NULL DEFAULT '{}'::jsonb,
